def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    color = next(v for row in grid for v in row if any(x != v for rr in grid for x in rr))
    # Connect every pair of cells of the non-background color sharing a row or column.
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != color]
    # determine actual foreground as most frequent? ARC demos use sparse marker and uniform background.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = [(r,c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    for i, (r1,c1) in enumerate(points):
        for r2,c2 in points[i+1:]:
            if r1 == r2:
                for c in range(min(c1,c2)+1, max(c1,c2)):
                    if grid[r1][c] == bg: out[r1][c] = 3
            elif c1 == c2:
                for r in range(min(r1,r2)+1, max(r1,r2)):
                    if grid[r][c1] == bg: out[r][c1] = 3
    return out

